class Solution {
public:
    int minimumSeconds(vector<int>& nums) {
        int n = nums.size();
        unordered_map<int, vector<int>> pos;
        for (int i = 0; i < n; i++) {
            pos[nums[i]].push_back(i);
        }

        int ans = n;
        for (auto& [val, indices] : pos) {
            int m = indices.size();
            int maxGap = 0;
            for (int i = 0; i < m; i++) {
                int gap = indices[(i + 1) % m] - indices[i];
                if (i == m - 1) gap += n;
                maxGap = max(maxGap, gap);
            }
            ans = min(ans, maxGap / 2);
        }
        return ans;
    }
};
